        return new ClienteLlmDoble((solicitud, n) =>
        {
            var llamadas = n == 0 ? LlamarTodas(solicitud.Herramientas, estudianteIdParaCoordinador) : [];
            return llamadas.Count > 0
                ? new RespuestaLlm(null, llamadas, uso ?? UsoPorDefecto, false)
                : new RespuestaLlm(redactor(solicitud), [], uso ?? UsoPorDefecto, false);
        });
    }

