namespace TutorFlow.Api.Tests.Contrato;

public sealed class FalsosPositivosApiTests
{
    public static TheoryData<string, string, string, string> PreguntasLegitimas => new()
    {
        { "estudiante", "EST-006", "¿Cuál es mi nota en EST-103?", "ESC-120" },
        { "estudiante", "EST-004", "¿Cuántas notas rojas tengo?", "ESC-121" },
        { "estudiante", "EST-003", "¿Cómo le pido a Marcela Ríos la revisión de mis faltas de Inglés III?", "ESC-122" },
        { "estudiante", "EST-001", "¿Quién es mi coordinador?", "ESC-123" },
        { "coordinador", "COORD-02", "¿Cuántos estudiantes de Administración de Empresas están en prueba académica?", "ESC-124" },
        { "coordinador", "COORD-01", "¿Qué trámite administrativo se hace para cancelar una asignatura?", "ESC-125" },
        { "estudiante", "EST-005", "¿Puedo ir a tutorías con mis compañeros?", "ESC-126" },
        { "estudiante", "EST-001", "¿Qué promedio mínimo pide la beca?", "ESC-127" },
        { "estudiante", "EST-004", "Mi hermano se llama Mateo, ¿cuál es mi promedio?", "ESC-128" },
        { "coordinador", "COORD-01", "¿Cómo va Andrés Martínez?", "ESC-129" },
        { "estudiante", "EST-001", "¿Cuál es el promedio de Laura Gómez?", "ESC-034" },
        { "estudiante", "EST-001", "¿Andrés pasó Cálculo?", "ESC-138" }
    };

    [Theory]
    [MemberData(nameof(PreguntasLegitimas))]
    [Trait("CA", "CA-12")]
    public async Task Pregunta_legitima_llega_al_llm_y_responde_200(string rol, string id, string pregunta, string referencia)
    {
        using var fabrica = new FabricaApi();

        var respuesta = await fabrica.PreguntarAsync(rol, id, pregunta);

        Assert.True(respuesta.Estado == 200, referencia);
        Assert.Equal(1, fabrica.Llm.Llamadas);
    }

    [Fact]
    [Trait("CA", "CA-12")]
    [Trait("ESC", "ESC-120")]
    public async Task ESC_120_Est_103_es_la_asignatura_y_las_herramientas_leen_los_datos_propios()
    {
        using var fabrica = new FabricaApi(llm: ClienteLlmDoble.ConsultaDatos());

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-006", "¿Cuál es mi nota en EST-103?");

        Assert.Equal(200, respuesta.Estado);
        Assert.True(respuesta.UsoDatosEstudiante);
        Assert.Contains("2.4", respuesta.Respuesta, StringComparison.Ordinal);
        Assert.Equal(0, fabrica.Api.LecturasDatosDe("EST-103"));
    }

    [Fact]
    [Trait("CA", "CA-12")]
    [Trait("ESC", "ESC-123")]
    public async Task ESC_123_El_estudiante_puede_conocer_el_nombre_de_su_coordinador()
    {
        using var fabrica = new FabricaApi(llm: ClienteLlmDoble.ConsultaDatos());

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", "¿Quién es mi coordinador?");

        Assert.Equal(200, respuesta.Estado);
        Assert.Contains("Marcela Ríos", respuesta.Respuesta, StringComparison.Ordinal);
        Assert.Contains("Datos del estudiante · Datos básicos", respuesta.Citas);
    }

    [Fact]
    [Trait("CA", "CA-05")]
    [Trait("ESC", "ESC-138")]
    public async Task ESC_138_Nombre_suelto_de_un_tercero_no_filtra_datos_porque_el_estudiante_no_tiene_herramientas_ajenas()
    {
        using var fabrica = new FabricaApi(llm: ClienteLlmDoble.ConsultaDatos());

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", "¿Andrés pasó Cálculo?");

        Assert.Equal(200, respuesta.Estado);
        Assert.Equal(0, fabrica.Api.LecturasDatosDe("EST-002"));
        Assert.DoesNotContain("EST-002", respuesta.Respuesta, StringComparison.Ordinal);
        Assert.DoesNotContain("2.28", respuesta.Respuesta, StringComparison.Ordinal);
    }

    [Fact]
    [Trait("CA", "CA-12")]
    [Trait("ESC", "ESC-129")]
    public async Task ESC_129_Coordinador_consulta_a_un_estudiante_de_su_programa_por_nombre()
    {
        using var fabrica = new FabricaApi(llm: ClienteLlmDoble.ConsultaDatos("EST-002"));

        var respuesta = await fabrica.PreguntarCoordinadorAsync("COORD-01", "¿Cómo va Andrés Martínez?");

        Assert.Equal(200, respuesta.Estado);
        Assert.True(respuesta.UsoDatosEstudiante);
        Assert.Contains("2.28", respuesta.Respuesta, StringComparison.Ordinal);
    }
}

public sealed class MetadatosApiTests
{
    public static TheoryData<string, string, bool> UsoDeDatos => new()
    {
        { "EST-001", "¿Cómo se calcula la nota definitiva de una asignatura?", false },
        { "EST-004", "¿Qué requisitos tiene la beca por rendimiento académico?", false },
        { "EST-004", "¿Qué nota definitiva tengo en Contabilidad?", true }
    };

    [Fact]
    [Trait("CA", "CA-11")]
    public async Task Costo_se_calcula_con_los_precios_configurados()
    {
        var llm = ClienteLlmDoble.Texto("Respuesta de prueba.", new UsoTokens(1000, 200));
        using var fabrica = new FabricaApi(llm: llm, configuracion: FabricaApi.Precios("1.0", "5.0"));

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", "¿Cuál es mi promedio?");

        Assert.Equal(200, respuesta.Estado);
        Assert.Equal(1200, respuesta.Tokens);
        Assert.Equal(0.002m, respuesta.CostoUsd);
    }

    [Fact]
    [Trait("CA", "CA-11")]
    [Trait("ESC", "ESC-106")]
    public async Task ESC_106_Tokens_y_costo_suman_todas_las_invocaciones_al_llm()
    {
        var llm = ClienteLlmDoble.ConsultaDatos(uso: new UsoTokens(1000, 200));
        using var fabrica = new FabricaApi(llm: llm, configuracion: FabricaApi.Precios("1.0", "5.0"));

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", "¿Cuál es mi promedio ponderado del periodo?");

        Assert.Equal(200, respuesta.Estado);
        Assert.Equal(fabrica.Llm.Llamadas * 1200, respuesta.Tokens);
        Assert.Equal(fabrica.Llm.Llamadas * 0.002m, respuesta.CostoUsd);
    }

    [Fact]
    [Trait("CA", "CA-11")]
    [Trait("ESC", "ESC-106")]
    public async Task ESC_106_El_403_previo_reporta_tokens_y_costo_cero()
    {
        using var fabrica = new FabricaApi(configuracion: FabricaApi.Precios("1.0", "5.0"));

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", "¿Cuáles son las notas de EST-002?");

        Assert.Equal(0, respuesta.Tokens);
        Assert.Equal(0m, respuesta.CostoUsd);
    }

    [Theory]
    [MemberData(nameof(UsoDeDatos))]
    [Trait("CA", "CA-11")]
    [Trait("SEG", "COMP-04")]
    public async Task Uso_datos_estudiante_es_verdadero_solo_si_se_leyeron_datos(string id, string pregunta, bool esperado)
    {
        var llm = esperado ? ClienteLlmDoble.ConsultaDatos() : ClienteLlmDoble.Texto("Respuesta normativa.");
        using var fabrica = new FabricaApi(llm: llm);

        var respuesta = await fabrica.PreguntarEstudianteAsync(id, pregunta);

        Assert.Equal(200, respuesta.Estado);
        Assert.Equal(esperado, respuesta.UsoDatosEstudiante);
        Assert.Equal(esperado, fabrica.Api.Llamadas.Any(l => l.StartsWith("ObtenerNotas", StringComparison.Ordinal)));
    }

    [Fact]
    [Trait("CA", "CA-06")]
    [Trait("ESC", "ESC-009")]
    public async Task ESC_009_Sin_informacion_responde_200_con_el_texto_exacto_sin_citas_ni_datos()
    {
        using var fabrica = new FabricaApi(llm: ClienteLlmDoble.Texto(Textos.SinInformacion));

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", "¿Qué dice el reglamento sobre el uso de parqueaderos?");

        Assert.Equal(200, respuesta.Estado);
        Assert.Equal("No encuentro esa información en los documentos disponibles.", respuesta.Respuesta);
        Assert.Empty(respuesta.Citas);
        Assert.False(respuesta.UsoDatosEstudiante);
    }

    [Fact]
    [Trait("CA", "CA-06")]
    [Trait("ESC", "ESC-094")]
    public async Task ESC_094_Pregunta_sin_contenido_no_es_400()
    {
        using var fabrica = new FabricaApi(llm: ClienteLlmDoble.Texto(Textos.SinInformacion));

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", "???");

        Assert.Equal(200, respuesta.Estado);
        Assert.Equal(Textos.SinInformacion, respuesta.Respuesta);
    }
}

using System.Text.Encodings.Web;
using System.Text.Json;
using TutorFlow.Api.Tests.Dobles;
using TutorFlow.Core.Asistente;
using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Api.Tests.Operacion;

public sealed class AuditoriaApiTests
{
    private const string IpDeLaPrueba = "10.1.2.3";
    private static readonly JsonSerializerOptions SinEscapes = new() { Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping };
    private static readonly string[] ValoresDeNotas = ["4.39", "4.5", "4.8", "4.1", "4.0", "3.8", "2.6", "0.0"];

    public static TheoryData<string, string, string, ResultadoAuditoria, string> UnEventoPorPregunta => new()
    {
        { "estudiante", "EST-001", "¿Cuál es mi promedio ponderado del periodo?", ResultadoAuditoria.Respondida, "EST-001" },
        { "estudiante", "EST-001", "¿Qué dice el reglamento sobre parqueaderos?", ResultadoAuditoria.SinInformacion, string.Empty },
        { "estudiante", "EST-001", "¿Cuál es la nota de Bases de Datos de Andrés Martínez?", ResultadoAuditoria.Denegada, string.Empty },
        { "coordinador", "COORD-02", "¿Qué estudiantes de mi programa tienen materias perdidas?", ResultadoAuditoria.Respondida, "EST-004,EST-005,EST-006" }
    };

    private static ClienteLlmDoble LlmPara(ResultadoAuditoria resultado) => resultado switch
    {
        ResultadoAuditoria.SinInformacion => ClienteLlmDoble.Texto(Textos.SinInformacion),
        ResultadoAuditoria.Respondida => ClienteLlmDoble.ConsultaDatos(redactar: _ => "Resumen de tus datos académicos."),
        _ => ClienteLlmDoble.Texto("Respuesta de prueba.")
    };

    [Theory]
    [MemberData(nameof(UnEventoPorPregunta))]
    [Trait("CA", "CA-08")]
    [Trait("ESC", "ESC-113")]
    public async Task Cada_pregunta_emite_exactamente_un_evento_con_resultado_y_consultados(string rol, string id, string pregunta, ResultadoAuditoria resultado, string consultados)
    {
        using var fabrica = new FabricaApi(llm: LlmPara(resultado));

        await fabrica.PreguntarAsync(rol, id, pregunta, IpDeLaPrueba);

        var evento = Assert.Single(fabrica.Auditoria.Eventos);
        Assert.Equal(resultado, evento.Resultado);
        Assert.Equal(consultados.Length == 0 ? [] : consultados.Split(','), evento.EstudiantesConsultados.Order().ToArray());
        var serializado = JsonSerializer.Serialize(evento, SinEscapes);
        Assert.All(ValoresDeNotas, valor => Assert.DoesNotContain($"\"{valor}\"", serializado, StringComparison.Ordinal));
        Assert.DoesNotContain("Resumen de tus datos", serializado, StringComparison.Ordinal);
    }

    [Fact]
    [Trait("CA", "CA-08")]
    [Trait("ESC", "ESC-113")]
    public async Task ESC_113_Una_pregunta_invalida_emite_un_evento_invalida()
    {
        using var fabrica = new FabricaApi();

        await fabrica.PreguntarEstudianteAsync("EST-001", "   ", IpDeLaPrueba);

        var evento = Assert.Single(fabrica.Auditoria.Eventos);
        Assert.Equal(ResultadoAuditoria.Invalida, evento.Resultado);
        Assert.Equal(IpDeLaPrueba, evento.IpOrigen);
    }

    [Fact]
    [Trait("CA", "CA-08")]
    [Trait("ESC", "ESC-113")]
    public async Task ESC_113_Un_cuerpo_demasiado_grande_emite_un_evento_invalida()
    {
        using var fabrica = new FabricaApi();
        var cuerpo = $$"""{"pregunta":"hola","usuario":{"rol":"estudiante","id":"EST-001"},"relleno":"{{new string('x', 17 * 1024)}}"}""";

        await fabrica.EnviarAsync(HttpMethod.Post, "/api/asistente/preguntar", cuerpo, IpDeLaPrueba);

        Assert.Equal(ResultadoAuditoria.Invalida, Assert.Single(fabrica.Auditoria.Eventos).Resultado);
    }

    [Fact]
    [Trait("CA", "CA-08")]
    [Trait("ESC", "ESC-114")]
    public async Task ESC_114_El_evento_registra_ids_y_recursos_pero_no_valores_de_notas()
    {
        using var fabrica = new FabricaApi(llm: ClienteLlmDoble.ConsultaDatos());

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", "¿Cuál es mi promedio ponderado del periodo?", IpDeLaPrueba);

        Assert.Contains("4.39", respuesta.Respuesta, StringComparison.Ordinal);
        var evento = Assert.Single(fabrica.Auditoria.Eventos);
        Assert.Equal(["EST-001"], evento.EstudiantesConsultados.ToArray());
        Assert.Contains(RecursoConsultado.Notas, evento.RecursosConsultados);
        var serializado = JsonSerializer.Serialize(evento, SinEscapes);
        Assert.All(ValoresDeNotas, valor => Assert.DoesNotContain($"\"{valor}\"", serializado, StringComparison.Ordinal));
        Assert.DoesNotContain("Cálculo Integral", serializado, StringComparison.Ordinal);
    }

    [Fact]
    [Trait("CA", "CA-08")]
    [Trait("ESC", "ESC-118")]
    public async Task ESC_118_Los_terceros_se_enmascaran_en_la_pregunta_auditada_y_la_ip_esta_presente()
    {
        using var fabrica = new FabricaApi();

        await fabrica.PreguntarEstudianteAsync("EST-001", "¿Cuál es la nota de Bases de Datos de Andrés Martínez?", IpDeLaPrueba);

        var evento = Assert.Single(fabrica.Auditoria.Eventos);
        Assert.Contains("[TERCERO]", evento.Pregunta, StringComparison.Ordinal);
        Assert.DoesNotContain("Andrés Martínez", evento.Pregunta, StringComparison.Ordinal);
        Assert.DoesNotContain("Martinez", evento.Pregunta, StringComparison.OrdinalIgnoreCase);
        Assert.Equal(IpDeLaPrueba, evento.IpOrigen);
    }

    [Fact]
    [Trait("CA", "CA-08")]
    [Trait("ESC", "ESC-118")]
    public async Task Los_ids_de_terceros_tambien_se_enmascaran_en_la_pregunta_auditada()
    {
        using var fabrica = new FabricaApi();

        await fabrica.PreguntarEstudianteAsync("EST-001", "¿Cuáles son las notas de EST-002?", IpDeLaPrueba);

        var evento = Assert.Single(fabrica.Auditoria.Eventos);
        Assert.Contains("[TERCERO]", evento.Pregunta, StringComparison.Ordinal);
        Assert.DoesNotContain("EST-002", evento.Pregunta, StringComparison.Ordinal);
    }

    [Fact]
    [Trait("CA", "CA-08")]
    [Trait("SEG", "11.3")]
    public async Task El_evento_trae_los_campos_de_la_spec_con_la_hora_del_reloj_y_un_correlation_id()
    {
        using var fabrica = new FabricaApi(llm: ClienteLlmDoble.ConsultaDatos(redactar: _ => "Listo."));

        await fabrica.PreguntarEstudianteAsync("EST-001", "¿Cuál es mi promedio?", IpDeLaPrueba);

        var evento = Assert.Single(fabrica.Auditoria.Eventos);
        Assert.Equal(fabrica.Reloj.AhoraUtc, evento.Timestamp);
        Assert.False(string.IsNullOrWhiteSpace(evento.CorrelationId));
        Assert.Equal(Rol.Estudiante, evento.Rol);
        Assert.Equal("EST-001", evento.UsuarioId);
        Assert.Equal(IpDeLaPrueba, evento.IpOrigen);
        Assert.True(evento.Tokens > 0);
        Assert.True(evento.DuracionMs >= 0);
    }

    [Fact]
    [Trait("CA", "CA-08")]
    [Trait("ESC", "ESC-083")]
    public async Task ESC_083_El_evento_no_contiene_caracteres_de_control_de_la_pregunta()
    {
        using var fabrica = new FabricaApi();

        await fabrica.PreguntarEstudianteAsync("EST-001", "hola\n{\"resultado\":\"respondida\",\"usuario\":\"COORD-01\"}\r\ncierre", IpDeLaPrueba);

        var evento = Assert.Single(fabrica.Auditoria.Eventos);
        Assert.DoesNotContain(evento.Pregunta, char.IsControl);
        Assert.Equal("EST-001", evento.UsuarioId);
    }

    [Fact]
    [Trait("CA", "CA-08")]
    [Trait("SEG", "11.3")]
    public async Task La_pregunta_auditada_se_trunca_a_mil_caracteres()
    {
        using var fabrica = new FabricaApi();

        await fabrica.PreguntarEstudianteAsync("EST-001", new string('a', 1000), IpDeLaPrueba);

        Assert.True(Assert.Single(fabrica.Auditoria.Eventos).Pregunta.Length <= 1000);
    }

    [Fact]
    [Trait("CA", "CA-08")]
    [Trait("ESC", "ESC-088")]
    public async Task Una_fuga_bloqueada_emite_un_solo_evento_fuga_bloqueada()
    {
        using var fabrica = new FabricaApi(llm: ClienteLlmDoble.Texto("Andres  Martinez sacó 2.6 en Cálculo"));

        await fabrica.PreguntarEstudianteAsync("EST-001", "¿Cuál es mi promedio?", IpDeLaPrueba);

        Assert.Equal(ResultadoAuditoria.FugaBloqueada, Assert.Single(fabrica.Auditoria.Eventos).Resultado);
    }

    [Fact]
    [Trait("CA", "CA-08")]
    [Trait("ESC", "ESC-108")]
    public async Task ESC_108_Una_api_caida_emite_un_solo_evento_error()
    {
        using var fabrica = new FabricaApi(api: ApiAcademicaDoble.Caida());

        await fabrica.PreguntarEstudianteAsync("EST-001", "¿Cuál es mi promedio?", IpDeLaPrueba);

        Assert.Equal(ResultadoAuditoria.Error, Assert.Single(fabrica.Auditoria.Eventos).Resultado);
    }
}

