        Assert.All(respuestas, r => Assert.Equal(200, r.Estado));
        var evento = Assert.Single(fabrica.Auditoria.MultiplesIdentidades);
        Assert.Equal(Ip, evento.IpOrigen);
        Assert.Equal(CuatroIds, evento.UsuarioIds.Order().ToArray());
    }

