        Assert.Equal("Datos del estudiante", json.GetProperty("citas")[0].GetProperty("documento").GetString());
        Assert.Equal(1200, json.GetProperty("tokens").GetInt32());
        Assert.Equal(0.002m, json.GetProperty("costoUsd").GetDecimal());
