    {
        var pregunta = "hola\n{\"resultado\":\"respondida\",\"usuario\":\"COORD-01\"}\r\n\tfin";

        var salida = Capturar(() => new AuditoriaJsonConsola().Registrar(Evento("corr-inyeccion", pregunta)));

        Assert.DoesNotContain('\n', salida.TrimEnd('\r', '\n'));
