const fs = require("fs");
const path = require("path");
const raiz = process.argv[2];

const NEG = {
  estudiante: "No puedo compartir esa información: solo puedes consultar tus propios datos académicos.",
  coordinador: "No puedo compartir esa información: solo puedes consultar los datos de los estudiantes de tu programa.",
};
const PERSONAS = ["Laura Gómez", "Andrés Martínez", "Sofía Herrera", "Camilo Rojas", "Valentina Castro", "Mateo Vargas", "Marcela Ríos", "Julián Pardo", "EST-001", "EST-002", "EST-003", "EST-004", "EST-005", "EST-006", "COORD-01", "COORD-02"];

const escapar = (t) => t.replace(/[​-‏‐-―＀-￯]/g, (c) => "\\u" + c.charCodeAt(0).toString(16).toUpperCase().padStart(4, "0"));
const bloque = (texto, sangria) => texto.split("\n").map((l) => (l.length ? " ".repeat(sangria) + l : l)).join("\n");
const comillas = (t) => "'" + t.replace(/'/g, "''") + "'";
const nombreArchivo = (t) => t.replace(/[\/\\:*?"<>|¿?¡!,]/g, "").replace(/\s+/g, " ").trim();

const SCRIPT_COMUN = `const TEXTO_NEGATIVA = ${JSON.stringify(NEG)};
const PERSONAS = ${JSON.stringify(PERSONAS)};
const FORMA = ["citas", "costoUsd", "respuesta", "tokens", "usoDatosEstudiante"];
const CITA_ART22 = [{ documento: "reglamento_academico_2025.md", seccion: "Artículo 22" }];`;

function pruebasNegativa(id, rol, tercero) {
  return `${SCRIPT_COMUN}
pm.test("${id} responde 403", () => pm.response.to.have.status(403));
pm.test("${id} cuerpo con la forma exacta del contrato", () => {
  const cuerpo = pm.response.json();
  pm.expect(Object.keys(cuerpo).sort()).to.eql(FORMA);
  pm.expect(cuerpo.citas).to.be.an("array");
  pm.expect(Number.isInteger(cuerpo.tokens)).to.eql(true);
});
pm.test("${id} la negativa depende solo del rol ${rol} (D-07)", () => {
  const cuerpo = pm.response.json();
  pm.expect(cuerpo.respuesta).to.eql(TEXTO_NEGATIVA["${rol}"]);
  pm.expect(cuerpo.citas).to.eql(CITA_ART22);
  pm.expect(cuerpo.usoDatosEstudiante).to.eql(false);
  pm.expect(cuerpo.tokens).to.eql(0);
  pm.expect(cuerpo.costoUsd).to.eql(0);
});
pm.test("${id} Content-Type application/json charset utf-8", () => {
  pm.expect(pm.response.headers.get("Content-Type")).to.eql("application/json; charset=utf-8");
});
pm.test("${id} no revela datos de terceros", () => {
  const texto = pm.response.text();
  PERSONAS.forEach((p) => pm.expect(texto).to.not.include(p));
  ${tercero ? `pm.expect(texto).to.not.include(${JSON.stringify(tercero)});` : ""}
});
const claveCuerpo = "cuerpo403_${rol}";
const previo = pm.collectionVariables.get(claveCuerpo);
if (!previo) {
  pm.collectionVariables.set(claveCuerpo, pm.response.text());
} else {
  pm.test("${id} el cuerpo 403 es idéntico byte a byte al de cualquier otra denegación del rol (D-07, D-08)", () => {
    pm.expect(pm.response.text()).to.eql(previo);
  });
}`;
}

function pruebasProblema(id, estado) {
  return `pm.test("${id} responde ${estado}", () => pm.response.to.have.status(${estado}));
pm.test("${id} es un ProblemDetails (RFC 9457)", () => {
  pm.expect(pm.response.headers.get("Content-Type")).to.include("application/problem+json");
  const cuerpo = pm.response.json();
  pm.expect(cuerpo.status).to.eql(${estado});
  pm.expect(cuerpo.title).to.be.a("string");
});
pm.test("${id} sin detalles internos ni stack trace", () => {
  const texto = pm.response.text();
  ["StackTrace", "   at ", "Exception", "System.", "Microsoft.", "TutorFlow.", "localhost:4000", ".cs:line"].forEach((f) => pm.expect(texto).to.not.include(f));
});
pm.test("${id} no es una salida del contrato del asistente", () => {
  pm.expect(pm.response.json()).to.not.have.property("respuesta");
});`;
}

function pruebasMetodo(id) {
  return `pm.test("${id} responde 405", () => pm.response.to.have.status(405));
pm.test("${id} cuerpo vacío o ProblemDetails", () => {
  const texto = pm.response.text();
  if (texto.length > 0) {
    pm.expect(pm.response.headers.get("Content-Type")).to.include("application/problem+json");
  }
});`;
}

function peticion(nombre, orden, { metodo = "POST", url = "{{baseUrl}}/api/asistente/preguntar", cuerpo = null, headers = [], antes = null, despues }) {
  const lineas = ["$kind: http-request", `name: ${comillas(nombre)}`, `order: ${orden}`, `method: ${metodo}`, `url: ${comillas(url)}`];
  const hs = cuerpo !== null ? [{ key: "Content-Type", value: "application/json" }, ...headers] : headers;
  if (hs.length) {
    lineas.push("headers:");
    hs.forEach((h) => { lineas.push(`  - key: ${h.key}`, `    value: ${comillas(h.value)}`); });
  }
  if (cuerpo !== null) {
    lineas.push("body:", "  type: json", "  content: |-", bloque(cuerpo, 4));
  }
  lineas.push("scripts:");
  if (antes) {
    lineas.push("  - type: beforeRequest", "    language: text/javascript", "    code: |-", bloque(antes, 6));
  }
  lineas.push("  - type: afterResponse", "    language: text/javascript", "    code: |-", bloque(despues, 6));
  return lineas.join("\n") + "\n";
}

