function definicion(ruta, nombre, orden, scripts) {
  fs.mkdirSync(path.join(ruta, ".resources"), { recursive: true });
  const l = ["$kind: collection", `name: ${comillas(nombre)}`];
  if (orden !== null) l.push(`order: ${orden}`);
  if (scripts) l.push("scripts:", "  - type: http:afterResponse", "    language: text/javascript", "    code: |-", bloque(scripts, 6));
  fs.writeFileSync(path.join(ruta, ".resources", "definition.yaml"), l.join("\n") + "\n", "utf8");
}

