    fs.writeFileSync(path.join(dir, `${nombreArchivo(p.nombre)}.request.yaml`), peticion(p.nombre, (i + 1) * 1000, p.opciones), "utf8");
    total++;
  });
}

const rend = path.join(raiz, "collections", "tutorflow-rendimiento");
