pm.test("${id} responde en menos de 500 ms", () => pm.expect(pm.response.responseTime).to.be.below(500));`;
  const nombre = `${id} denegacion rapida`;
  fs.writeFileSync(path.join(filtro, `${nombre}.request.yaml`), peticion(nombre, (i + 1) * 1000, { cuerpo, despues }), "utf8");
});

fs.mkdirSync(path.join(raiz, "environments"), { recursive: true });
